use std::sync::mpsc;
use std::time::Duration;

/// Helper to read back f32 values from a GPU buffer for diagnostic purposes.
fn readback_f32(device: &wgpu::Device, queue: &wgpu::Queue, buf: &wgpu::Buffer, n: usize) -> Vec<f32> {
    let size = (n * 4) as u64;
    let staging = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("diag_staging"),
        size,
        usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ,
        mapped_at_creation: false,
    });
    let mut enc = device.create_command_encoder(&wgpu::CommandEncoderDescriptor::default());
    enc.copy_buffer_to_buffer(buf, 0, &staging, 0, size);
    queue.submit(std::iter::once(enc.finish()));

    let slice = staging.slice(..);
    let (tx, rx) = mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| { let _ = tx.send(r); });

    loop {
        device.poll(wgpu::Maintain::Poll);
        if rx.try_recv().is_ok() { break; }
        std::thread::sleep(Duration::from_micros(10));
    }

    let data = slice.get_mapped_range();
    let vals: Vec<f32> = bytemuck::cast_slice(&data)[..n].to_vec();
    drop(data);
    staging.unmap();
    vals
}

pub fn execute_layer_diagnostic(
    device: &wgpu::Device,
    queue: &wgpu::Queue,
    pipelines: &LayerPipelines,
    config: &ModelConfig,
    weights: &LayerWeights,
    hidden_state: &wgpu::Buffer,
) {
    let h = config.hidden_dim;
    let i = config.intermediate_dim;
    let eps = config.rms_norm_eps;
    let tolerance = 0.01;

    // Helper to print and compare
    let mut check = |label: &str, actual: Vec<f32>, expected: Vec<f32>| {
        let mut passed = true;
        for (a, e) in actual.iter().zip(expected.iter()) {
            if (a - e).abs() > tolerance {
                passed = false;
                break;
            }
        }
        let status = if passed { "PASS" } else { "FAIL" };
        tracing::info!(
            "[{}] {} | Actual: {:?} | Expected: {:?} | Result: {}",
            status, label, actual, expected, status
        );
    };

    // 1. RMSNorm
    let norm_out = create_temp_buffer(device, "diag_norm_out", (h * 4) as u64);
    {
        let mut enc = device.create_command_encoder(&wgpu::CommandEncoderDescriptor::default());
        pipelines.rmsnorm.dispatch(device, queue, &mut enc, hidden_state, &weights.input_layernorm, &norm_out, h, 1, eps);
        queue.submit(std::iter::once(enc.finish()));
    }
    check("After FFN RMSNorm", readback_f32(device, queue, &norm_out, 4), vec![-0.03002, 0.18692, 0.48619, -1.04201]);

    // 2. Gate Proj
    let gate_out = create_temp_buffer(device, "diag_gate_out", (i * 4) as u64);
    {
        let mut enc = device.create_command_encoder(&wgpu::CommandEncoderDescriptor::default());
        dispatch_tiled_matmul(device, queue, &mut enc, pipelines, &norm_out, &weights.gate_proj, &gate_out, 1, h, i);
        queue.submit(std::iter::once(enc.finish()));
    }
    check("After gate_proj matvec", readback_f32(device, queue, &gate_out, 4), vec![-0.15846, 0.49651, -0.12629, 0.01424]);

    // 3. Up Proj
    let up_out = create_temp_buffer(device, "diag_up_out", (i * 4) as u64);
    {
        let mut enc = device.create_command_encoder(&wgpu::CommandEncoderDescriptor::default());
        dispatch_tiled_matmul(device, queue, &mut enc, pipelines, &norm_out, &weights.up_proj, &up_out, 1, h, i);
        queue.submit(std::iter::once(enc.finish()));
    }
    check("After up_proj matvec", readback_f32(device, queue, &up_out, 4), vec![0.18722, -1.51797, 0.37551, -0.11288]);

    // 4. SwiGLU (gate_out * up_out)
    let swiglu_out = create_temp_buffer(device, "diag_swiglu_out", (i * 4) as u64);
    {
        let mut enc = device.create_command_encoder(&wgpu::CommandEncoderDescriptor::default());
        dispatch_swiglu(device, queue, &mut enc, pipelines, &gate_out, &up_out, &swiglu_out, i);
        queue.submit(std::iter::once(enc.finish()));
    }
    check("After SwiGLU", readback_f32(device, queue, &swiglu_out, 4), vec![-0.01366, -0.46852, -0.02222, -0.00081]);

    // 5. Down Proj
    let down_out = create_temp_buffer(device, "diag_down_out", (h * 4) as u64);
    {
        let mut enc = device.create_command_encoder(&wgpu::CommandEncoderDescriptor::default());
        dispatch_tiled_matmul(device, queue, &mut enc, pipelines, &swiglu_out, &weights.down_proj, &down_out, 1, i, h);
        queue.submit(std::iter::once(enc.finish()));
    }
    check("After down_proj matvec", readback_f32(device, queue, &down_out, 4), vec![-0.15616, -0.06285, -0.41493, 0.24988]);

    // 6. Residual Add (down_out + hidden_state)
    let final_out = create_temp_buffer(device, "diag_final_out", (h * 4) as u64);
    {
        let mut enc = device.create_command_encoder(&wgpu::CommandEncoderDescriptor::default());
        dispatch_add(device, queue, &mut enc, pipelines, &down_out, hidden_state, &final_out, h);
        queue.submit(std::iter::once(enc.finish()));
    }
    check("After residual add", readback_f32(device, queue, &final_out, 4), vec![-0.15722, -0.05969, -0.40335, 0.23199]);
}
